// ---------------------------------------------------------------------------
// Theme handling: light, dark or follow the operating system.
//
// Adapted from PIDDojo src/main.ts + src/styles.css (Martin Oberzalek, MIT):
// the `data-theme` attribute on <html>, the localStorage key and the `color-scheme`
// declaration follow the same approach. Extended with the "auto" mode that the
// PID Dojo does not have.
// ---------------------------------------------------------------------------

import type { ThemeMode } from './types';

const THEME_KEY = 'pi-sensor-theme';
const DARK_QUERY = '(prefers-color-scheme: dark)';

function loadMode(): ThemeMode {
  try {
    const stored = localStorage.getItem(THEME_KEY);
    if (stored === 'light' || stored === 'dark' || stored === 'auto') return stored;
  } catch {
    // Private mode / disabled storage: just fall back to "auto".
  }
  return 'auto';
}

function storeMode(mode: ThemeMode): void {
  try {
    localStorage.setItem(THEME_KEY, mode);
  } catch {
    // Persisting the choice is best effort.
  }
}

export type ThemeListener = (dark: boolean) => void;

export class ThemeController {
  private mode: ThemeMode;
  private readonly media: MediaQueryList;
  private readonly listeners = new Set<ThemeListener>();

  constructor() {
    this.mode = loadMode();
    this.media = window.matchMedia(DARK_QUERY);
    this.media.addEventListener('change', () => {
      if (this.mode === 'auto') this.apply();
    });
  }

  getMode(): ThemeMode {
    return this.mode;
  }

  isDark(): boolean {
    return this.resolveDark();
  }

  setMode(mode: ThemeMode): void {
    this.mode = mode;
    storeMode(mode);
    this.apply();
  }

  /** Cycle light -> dark -> auto, used by the header button. */
  cycle(): ThemeMode {
    const order: ThemeMode[] = ['light', 'dark', 'auto'];
    const index = order.indexOf(this.mode);
    const next = order[(index + 1) % order.length] ?? 'auto';
    this.setMode(next);
    return next;
  }

  onChange(listener: ThemeListener): void {
    this.listeners.add(listener);
  }

  /** Push the current theme into the DOM and notify every listener. */
  apply(): void {
    const dark = this.resolveDark();
    document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');
    document.documentElement.style.colorScheme = dark ? 'dark' : 'light';
    for (const listener of this.listeners) listener(dark);
  }

  private resolveDark(): boolean {
    if (this.mode === 'dark') return true;
    if (this.mode === 'light') return false;
    return this.media.matches;
  }
}
